'use strict';

// MODULES //

var pkg2alias = require( '@stdlib/namespace/pkg2alias' );
var isNull = require( '@stdlib/assert/is-null' );
var format = require( '@stdlib/string/format' );


// VARIABLES //

var RE_EXTERNAL_ALIAS = /{{alias:([\s\S]+?)}}/g;
var RE_NEWLINE = /\r?\n/g;


// FUNCTIONS //

/**
* Counts the number of lines in a string.
*
* @private
* @param {string} str - input string
* @returns {PositiveInteger} number of lines
*/
function countLines( str ) {
	return ( str.match( RE_NEWLINE ) || '' ).length;
}


// MAIN //

/**
* Rule for enforcing that aliased packages are resolvable.
*
* @param {Context} context - lint context
* @returns {Object} validators
*/
function main( context ) {
	/**
	* Checks that all aliased packages are resolvable.
	*
	* @private
	* @param {Object} ast - full AST
	*/
	function resolvableAliases( ast ) {
		var substr;
		var alias;
		var match;
		var line;
		var pos;

		match = RE_EXTERNAL_ALIAS.exec( ast.raw );
		while ( !isNull( match ) ) {
			alias = pkg2alias( match[ 1 ] );
			if ( !alias ) {
				substr = ast.raw.substring( 0, RE_EXTERNAL_ALIAS.lastIndex );
				line = countLines( substr );
				pos = {
					'start': ast.start + line,
					'end': ast.start + line
				};
				context.report( format( '%s does not have an alias in the global REPL namespace', match[ 1 ] ), pos );
			}
			// Resolve the next match:
			match = RE_EXTERNAL_ALIAS.exec( ast.raw );
		}
	}
	return {
		'function': resolvableAliases
	};
}


// EXPORTS //

module.exports = main;
